(()=>{
const S=Site,D=FrameData,{esc,art,link,button}=S;let uploadURLs={},toolTimers=new Map();
const currentTool=()=>D.tools.find(t=>t.id===(S.context.parts[0]==='app'?S.context.parts[2]:S.context.parts[1]));
const record=t=>S.state.results[t.id];
function toolList(){S.pageTitle='创作工具中心';const items=D.tools.filter(t=>!t.hidden).filter(t=>(S.ui.toolGroup==='全部'||t.group===S.ui.toolGroup)&&(t.title+t.desc+t.group).includes(S.ui.toolQuery));return `<main class="wrap"><section class="tools-hero"><div><span class="eyebrow">A LITTLE HELP FOR YOUR BIG IDEAS</span><h1>创作的每一步，<br>都有顺手的小工具。</h1><p>从一个角色、一格画面开始。<br>先体验，再把喜欢的结果带进你的故事。</p><span class="subtle-note">14 个独立工具 · 本机示例体验 · 无真实 API 调用</span></div><div class="tools-hero-art">${art(8,'原创角色特写')}<span>YOUR CHARACTER,<br>MORE POSSIBILITIES.</span><b>✧</b></div></section><div class="tools-toolbar"><div class="filter-row">${['全部','角色资产','漫画编辑','动态演绎','故事创作','工作室效率'].map(g=>button(g,'tool-filter','filter '+(S.ui.toolGroup===g?'selected':''),`data-value="${g}"`)).join('')}</div><label class="search-box">⌕<input id="tool-search" placeholder="搜索工具、能力或结果…" value="${esc(S.ui.toolQuery)}" aria-label="搜索工具"></label></div><div class="results-heading"><span>为你的下一步创作</span><small id="tool-count">${items.length} 个工具</small></div><div class="tool-grid" id="tools-grid">${items.map(S.public.toolCard).join('')||'<p class="muted">没有匹配的工具，请换个关键词。</p>'}</div><section class="section tool-bridge"><span>↗</span><div><h2>每个小结果，都能成为大故事的一部分。</h2><p>生成角色后保存到资产库，切格后进入章节分镜，动态预览直接继续成为你的镜头。</p></div>${link('看看完整创作空间 →','/product','button ghost')}</section><section class="section">${S.sectionHead('BEFORE YOU BEGIN','关于工具体验。')}${S.faq(D.faqs.slice(3))}</section></main>`;}
function defaultPrompt(t){return ['oc-sheet','storyboard'].includes(t.id)?t.id==='oc-sheet'?'林夏，26 岁插画师。深色长发，红色围巾，米色风衣。雨天重回街角书店，温柔、安静，眼神坚定。':'林夏推开旧书店的门，陈序从书架后抬头。两人隔着雨声重逢，她拿出一封未寄出的信。':'保持角色身份、服装和画风一致，使用《雨停之前》示例演示工具流程。';}
function detail(t){S.pageTitle=t.title;const r=record(t);return `<main class="wrap tool-detail">${S.crumbs([['创作工具','/tools'],[t.group,'/tools'],[t.title,null]])}<section class="tool-heading"><div><span class="eyebrow">${t.en}</span><h1>${t.title}</h1><p>${t.desc}</p></div><span class="status-badge ${t.stage==='P2'?'amber':''}">${t.stage==='P2'?'高级能力 · 流程演示':'可匿名体验示例'}</span></section><div class="tool-workbench"><section class="tool-input surface"><div class="panel-heading"><span>01 / 输入与设置</span><small>${t.stage}</small></div><form data-form="tool" data-id="${t.id}"><label>${t.input}</label>${['sheet','storyboard'].includes(t.kind)?`<textarea name="prompt" id="tool-prompt" required minlength="10" rows="6" placeholder="描述角色外貌、服装和性格…">${esc(r?.prompt||defaultPrompt(t))}</textarea>`:`<label class="upload-area" for="tool-file"><input type="file" id="tool-file" accept="${['quality'].includes(t.kind)?'image/*,video/*':t.kind==='rig'?'image/*,.psd':'image/*'}" ${['checks','panels','batch','continuity'].includes(t.kind)?'multiple':''}><span id="upload-preview">${uploadURLs[t.id]?`<img src="${uploadURLs[t.id]}" alt="本机输入预览">`:'<b>↥</b><strong>选择本机素材</strong><small>仅本机预览，不上传</small>'}</span></label>`}<div class="sample-row">${button('↺ 使用示例素材','tool-sample','text-link',`data-id="${t.id}"`)}<span id="input-source">${r?.source==='upload'?'本机素材已选择':r?.ready?'已加载示例':'也可以直接体验示例'}</span></div><label>${t.param}<select name="option" id="tool-option">${t.options.map(v=>`<option ${r?.option===v?'selected':''}>${v}</option>`).join('')}</select></label>${!['sheet','storyboard'].includes(t.kind)?`<label>补充说明<textarea name="prompt" id="tool-prompt" rows="3">${esc(r?.prompt||defaultPrompt(t))}</textarea></label>`:''}<div class="tool-note"><span>✧</span><p>本工具使用原创示例结果演示。你选择的文件只在本机预览，点击后不会发起模型调用。</p></div><button class="button primary full" id="run-tool">${r?.status==='ready'?'重新演示':'生成示例结果'} <span>↗</span></button></form></section><section class="tool-result surface"><div class="panel-heading"><span>02 / ${t.output}</span><span class="status-badge" id="result-status">${r?.status==='ready'?'示例结果已就绪':'等待开始'}</span></div><div id="tool-result-body">${r?.status==='ready'?result(t,r):`<div class="result-placeholder"><div class="placeholder-art">${art(t.art,t.title)}<span>${t.icon}</span></div><h3>先试一次，看看你的创作可能。</h3><p>示例结果会出现在这里，可下载、保存或继续制作。</p>${button('用示例开始体验','tool-sample','button ghost',`data-id="${t.id}"`)}</div>`}</div><div id="tool-result-actions" ${r?.status==='ready'?'':'hidden'}>${resultActions(t)}</div></section></div><section class="section tool-how">${S.sectionHead('A SMALL STEP FORWARD','使用这个工具，接下来可以做什么？')}<div class="process-grid three">${[['01','输入或选择示例','使用你自己的描述和本机素材，或直接加载预置示例。'],['02','检查并调整结果','在结果区查看工具输出。更改选项可以重新体验。'],['03','带进你的故事',`将结果保存为${t.asset}，加入已有项目或创建一个新项目。`]].map(([n,h,p])=>`<div><span>${n}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section><section class="section">${S.sectionHead('KEEP CREATING','也许下一步，你会用到。')}<div class="tool-grid three">${D.tools.filter(t=>!t.hidden).filter(x=>x.id!==t.id&&(x.group===t.group||x.stage==='P0')).slice(0,3).map(S.public.toolCard).join('')}</div></section></main>`;}
function resultActions(t){return `<div class="result-action-row">${button('保存到资产库','save-tool','button primary',`data-id="${t.id}"`)}${button('加入项目 ↗','tool-project','button ghost',`data-id="${t.id}"`)}${button('下载结果','download-tool','button ghost',`data-id="${t.id}"`)}</div><p class="result-disclaimer">结果为原创示例，不是针对上传文件的真实 AI 处理。高级文件格式、视频与 PSD 当前提供示例说明清单。</p>`;}
function result(t,r){
 const picture=(v,label,cls='')=>`<div class="result-picture ${cls}">${art(v,label)}${label?`<span>${esc(label)}</span>`:''}</div>`;
 const row=(title,desc,status='需确认')=>`<div class="inspection-row"><span class="inspection-dot ${status==='通过'?'good':''}">${status==='通过'?'✓':'!'}</span><div><strong>${title}</strong><p>${desc}</p></div><span class="status-badge ${status==='通过'?'':'amber'}">${status}</span></div>`;
 if(t.kind==='sheet')return `<div class="oc-sheet"><div class="oc-header"><span>ORIGINAL CHARACTER / 001</span><h2>${esc(r.characterName||'林夏')} <small>CHARACTER SHEET</small></h2></div><div class="oc-views">${[1,8,6].map((v,i)=>picture(v,['肖像参考','表情参考','服装参考'][i])).join('')}</div><div class="oc-notes"><div><label>外貌与服装</label><p>${esc(r.prompt)}</p></div><div><label>画风约束</label><p>${esc(r.option)} · 同一身份 · 版本 v1</p><small>多视图以同角色故事画面示意，非真实三视图生成。</small></div></div></div>`;
 if(t.kind==='panels')return `<div class="panel-results"><div class="result-summary"><strong>识别 4 个示例分格</strong><span>顺序可调整 · OCR 可修改</span></div><div class="panel-result-grid">${(r.order||[0,1,2,3]).map((v,i)=>`<div class="panel-result-card">${picture(v,'分格 '+(i+1))}<label>对白 ${i+1}<input data-result-dialogue="${i}" aria-label="分格 ${i+1} 对白" value="${esc(r.dialogues?.[i]||['那家书店，还在原来的地方。','七年了，你还记得我吗？','我以为，你不会再来了。','有些话，写了很久也没寄出去。'][v])}"></label><div class="row between"><small>${v===2?'◈ 归属待确认':'✓ 阅读顺序已识别'}</small>${button('↑','panel-up','mini-button',`data-index="${i}" aria-label="上移分格 ${i+1}" ${i===0?'disabled':''}`)}</div></div>`).join('')}</div></div>`;
 if(t.kind==='motion')return `<div class="motion-tool"><div class="motion-demo is-playing" id="tool-motion-frame">${art(t.art,'10 秒视频示意')}<span class="motion-subtitle">七年了，你还记得我吗？</span><b>9:16</b></div><div class="motion-tool-controls">${button('Ⅱ 暂停','tool-motion','button ghost')}<span>10 秒 · ${esc(r.option)} · 稳定动画示意</span></div><div class="segmented-result">${button('稳定底稿','motion-channel','filter selected','data-value="stable"')}${button('增强候选示意','motion-channel','filter','data-value="enhanced"')}</div><p class="muted" id="channel-note">稳定底稿可编辑，无真实视频输出。</p></div>`;
 if(['checks','continuity','quality'].includes(t.kind)){const rows=t.kind==='checks'?[['服装连续性','第 03 格围巾颜色与参考不一致。','需确认'],['角色身份','示例中的发型与脸型参考一致。','通过'],['表情变化','第 04 格笑容明显，建议人工确认。','需确认']]:t.kind==='continuity'?[['第 02 章 / 服装','林夏的围巾由红色变为浅色，需要剧情解释。','需确认'],['第 01 → 02 章 / 道具','信封状态从未拆封变为已展开。','需确认'],['场景关系','两章沿用慢日子书店资产 v1。','通过']]:[['00:14 / 字幕安全区','镜头 04 的字幕接近底部操作区。','需确认'],['00:39 / 角色表情','镜头 09 与锁定表情参考存在差异。','需确认'],['黑帧与画面尺寸','示例检查通过，真实文件未检测。','通过']];return `<div class="quality-result"><div class="quality-overview">${picture(t.art,'参考画面')}<div><span class="eyebrow">DEMO INSPECTION</span><h2>2 项需要你看一眼。</h2><p>规则：${esc(r.option)}<br>按镜头处理，保留已有结果。</p></div></div>${rows.map(v=>row(...v)).join('')}<p class="muted">仅示例报告，未对上传文件进行真实检测。</p></div>`;}
 if(t.kind==='puppet')return `<div class="puppet-result"><div class="puppet-stage" id="puppet-stage">${art(t.art,'PNGTuber 角色演示')}<span id="puppet-label">睁眼 · 闭嘴</span></div><div class="state-buttons">${['睁眼 · 闭嘴','睁眼 · 张嘴','闭眼 · 闭嘴','闭眼 · 张嘴'].map((v,i)=>button(v,'puppet-state','filter '+(i===0?'selected':''),`data-index="${i}"`)).join('')}</div><p class="muted">四状态切换交互示意；图像使用同一幅插画，未真实绘制嘴型。</p></div>`;
 if(t.kind==='expressions')return `<div><div class="result-summary"><strong>${esc(r.option)}</strong><span>林夏 / 同角色参考集</span></div><div class="expression-grid">${['平静','微笑','惊讶','回望','低头','期待'].map((v,i)=>picture([1,8,3,6,4,9][i],v)).join('')}</div><p class="muted">此图集用于表现参考集组织，表情与姿势变化未调用模型生成。</p></div>`;
 if(t.kind==='lettering')return `<div class="lettering-result"><div class="two-col"><div class="lettering-image">${art(3,'原始中文对白')}<span class="bubble original">有些话，写了很久<br>也没寄出去。</span><small>原始对白</small></div><div class="lettering-image">${art(3,'翻译排字预览')}<span class="bubble translated" id="translated-bubble">${r.option==='日语'?'ずっと、伝えたかった。':r.option==='简体中文'?'有些话，终于能说出口。':"Some words took years<br>to find their way to you."}</span><small>${esc(r.option)} · 重排示意</small></div></div><label>调整结果对白<textarea id="translated-text">${r.option==='英语'?'Some words took years to find their way to you.':r.option==='日语'?'ずっと、伝えたかった。':'有些话，终于能说出口。'}</textarea></label></div>`;
 if(t.kind==='color')return `<div class="color-result"><div class="color-comparison"><div class="line-art">${art(t.art,'线稿清理示意')}<span>线稿示意</span></div><div>${art(t.art,'上色示意')}<span>${esc(r.option)}</span></div></div><div class="swatches">${['#647a85','#99a9aa','#d7c6a5','#9b5658','#4e5662'].map(c=>`<span style="background:${c}" title="${c}"></span>`).join('')}<small>参考色板 · CSS 线稿效果演示</small></div></div>`;
 if(['layers','rig','live2d'].includes(t.kind)){
   const binding=t.kind!=='layers',merged=t.kind==='live2d';
   return `${merged?'<p class="ts-note">角色输入 → 分层与补画 → 绑定与动作预览</p>':''}<div class="layer-result"><div class="layer-preview ${binding?'rig-preview':''}">${art(t.art,'角色分层与绑定示例')}<i class="layer-guide g1"></i><i class="layer-guide g2"></i><i class="layer-guide g3"></i>${binding?'<b class="rig-point p1"></b><b class="rig-point p2"></b><b class="rig-point p3"></b>':''}</div><div class="layer-tree"><h3>${merged?'分层结构与补画建议':binding?'绑定检查 / 参数建议':'建议图层结构'}</h3>${['角色 / 林夏','　头发 / 前发 + 后发','　脸部 / 眼睛 + 眉毛 + 嘴','　服装 / 围巾 + 风衣','　身体 / 躯干 + 手臂','背景 / 独立图层'].map((v,i)=>`<div><span>▱ ${v}</span><span class="status-badge ${i===2?'amber':''}">${i===2?'需补画':'示例'}</span></div>`).join('')}<p class="muted">${binding?'建议补齐被遮挡的眼部与后发区域，再进行绑定。':'建议补齐被遮挡的眼部与后发区域。PSD 导出当前仅提供分层说明清单。'}</p>${merged?'<h3>绑定与动作预览</h3><p class="muted">头部 X/Y、眨眼、口型和呼吸为绑定参数建议。下方拖动仅旋转示例整图，未进行真实网格绑定。</p>':''}${binding?'<label>头部转动示意<input type="range" min="-15" max="15" value="0" id="rig-range" aria-label="头部转动示意"></label>':''}<p class="muted">${merged?'本机流程示例，可保存、下载分层与绑定方案；未生成 PSD、Live2D 模型或真实绑定文件。':binding?'头部 X/Y、眨眼和呼吸参数为建议值，无真实绑定文件。':''}</p></div></div>`;
 }
 if(t.kind==='storyboard')return `<div><div class="result-summary"><strong>连续分镜 / ${esc(r.option)}</strong><span>角色：林夏、陈序</span></div><div class="storyboard-result">${[0,1,2,3].map((v,i)=>`<div>${picture(v,'0'+(i+1))}<h4>${['建立书店与雨景','林夏推门抬头','陈序回应目光','信封作为情绪转折'][i]}</h4><p>${['远景 · 5 秒','特写 · 4 秒','中近景 · 5 秒','物件特写 · 5 秒'][i]}</p></div>`).join('')}</div><p class="muted">剧情描述已保留，画面使用固定示例，不是真实实时生成。</p></div>`;
 if(t.kind==='batch')return `<div class="batch-result"><div class="result-summary"><strong>4 份示例素材 · ${esc(r.option)}</strong><span>3 完成 / 1 待处理</span></div>${[1,2,0,7].map((v,i)=>`<div class="batch-row">${art(v)}<div><strong>${['linxia_reference_001','chenxu_reference_001','bookshop_scene_001','street_scene_001'][i]}.png</strong><small>${i===3?'原始画面比例不同，需要确认裁切':'1080 × 810 · 命名规则已应用'}</small></div><span class="status-badge ${i===3?'amber':''}">${i===3?'需确认':'完成'}</span></div>`).join('')}</div>`;
 return '';
}
function loadSample(t){const existing=record(t)||{};S.state.results[t.id]={...existing,ready:true,prompt:existing.prompt||defaultPrompt(t),source:'sample',option:existing.option||t.options[0]};delete uploadURLs[t.id];S.save();S.render();S.toast('已加载《雨停之前》原创示例。');}
function run(form){const t=D.tools.find(v=>v.id===form.dataset.id);if(!t)return;const values=Object.fromEntries(new FormData(form));const prior=record(t)||{};const r={...prior,prompt:values.prompt||defaultPrompt(t),option:values.option,source:uploadURLs[t.id]?'upload':'sample',characterName:t.kind==='sheet'?(values.prompt.split(/[，,。\n]/)[0].slice(0,18)||'我的角色'):'林夏',status:'working',generatedAt:new Date().toISOString()};S.state.results[t.id]=r;S.save();S.$('#tool-result-body').innerHTML=`<div class="generating-state"><div class="orbit">✧</div><h3>正在整理${t.output}…</h3><p>本地流程演示，不调用模型</p><progress id="tool-progress" max="100" value="5"></progress></div>`;S.$('#result-status').textContent='演示处理中';S.$('#tool-result-actions').hidden=true;const submit=S.$('#run-tool');submit.disabled=true;let n=5;clearInterval(toolTimers.get(t.id));const timer=setInterval(()=>{n+=25;const p=S.$('#tool-progress');if(p)p.value=Math.min(n,100);if(n>=100){clearInterval(timer);toolTimers.delete(t.id);r.status='ready';S.save();if(S.context.path==='/tools/'+t.id||S.context.path==='/app/tools/'+t.id){S.$('#tool-result-body').innerHTML=result(t,r);S.$('#tool-result-actions').hidden=false;S.$('#result-status').textContent='示例结果已就绪';submit.disabled=false;submit.textContent='重新演示 ↗';}S.toast(t.title+'示例已就绪。');}},300);toolTimers.set(t.id,timer);}
function saveResult(toolId){const t=D.tools.find(v=>v.id===toolId),r=t&&record(t);if(!r||r.status!=='ready'){S.toast('请先生成示例结果。');return;}if(!S.context.path.startsWith('/app/')&&S.requireUser({action:'save-tool',tool:toolId}))return;let asset=S.state.assets.find(a=>a.resultId===toolId&&(!S.context.path.startsWith('/app/')||a.projectId===Cimora.ctx().p.id));if(!asset){asset={id:S.id('asset'),name:t.kind==='sheet'?(r.characterName+' · 设定表'):t.title+' · 示例结果',type:t.asset,art:t.art,version:1,locked:false,desc:r.prompt,resultId:toolId};S.state.assets.unshift(asset);r.assetId=asset.id;S.save();}if(S.context.path.startsWith('/app/')){const c=Cimora.ctx();asset.projectId=c.p.id;asset.chapterIds??=[];if(!asset.chapterIds.includes(c.c.id))asset.chapterIds.push(c.c.id);c.e.bindings[asset.id]=asset.version;c.p.assetIds??=[];if(!c.p.assetIds.includes(asset.id))c.p.assetIds.push(asset.id);S.save();}S.modal('结果已保存，继续你的故事。',`<div class="saved-result">${art(t.art,t.title)}<div><span class="status-badge">已保存为${t.asset}</span><h3>${esc(asset.name)}</h3><p>来源与参数一起保留，可加入已有项目或从这里新建。</p></div></div>`,`<a class="button ghost" href="#/app/assets/${asset.id}">查看资产</a><button class="button primary" data-act="tool-project" data-id="${t.id}">加入项目 ↗</button>`);}
function chooseProject(toolId){const t=D.tools.find(v=>v.id===toolId);if(!record(t)||record(t).status!=='ready'){S.toast('先生成一个示例结果，再加入项目。');return;}if(!S.context.path.startsWith('/app/')&&S.requireUser({action:'save-tool',tool:toolId}))return;const projects=S.state.projects.filter(p=>!p.archived);S.modal('将结果带进你的故事',`<p>为${esc(t.title)}的结果选择去处。</p><div class="project-pick-list">${projects.map(p=>button(`${art(p.art,p.name)}<span><strong>${esc(p.name)}</strong><small>${p.chapters.length} 个章节</small></span><b>↗</b>`,'attach-tool','project-pick',`data-id="${toolId}" data-project="${p.id}"`)).join('')}</div>`,`<a class="button primary" href="#/app/new?tool=${toolId}">＋ 新建项目并使用结果</a>`);}
function attach(toolId,pid){const t=D.tools.find(v=>v.id===toolId),p=S.project(pid),r=record(t);if(!p||!r)return;let a=S.state.assets.find(a=>a.resultId===toolId&&(!S.context.path.startsWith('/app/')||a.projectId===Cimora.ctx().p.id));if(!a){a={id:S.id('asset'),name:t.kind==='sheet'?r.characterName+' · 设定表':t.title+'结果',type:t.asset,art:t.art,version:1,locked:false,desc:r.prompt,resultId:toolId};S.state.assets.unshift(a);}p.assetIds??=[];if(!p.assetIds.includes(a.id))p.assetIds.push(a.id);p.toolSource=toolId;S.save();S.close();S.route('/app/projects/'+p.id);S.toast('结果与来源已加入项目，可继续制作。');}
async function downloadResult(t){const r=record(t);if(!r)return;const visual=['sheet','motion','puppet','expressions','lettering','color','storyboard','panels'].includes(t.kind);if(!visual){S.download({prototype:true,tool:t.title,...r,notice:'示例说明清单，不含真实 PSD、绑定或模型检测结果'},'framein-'+t.id+'-demo.json');return;}try{const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=t.kind==='sheet'?1080:900;const ctx=canvas.getContext('2d');ctx.fillStyle='#eee8df';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#47414b';ctx.font='bold 38px sans-serif';ctx.fillText(t.title+' · 原创示例',50,70);const nums=['sheet','expressions','storyboard','panels'].includes(t.kind)?[t.art,8,6]:[t.art];for(let i=0;i<nums.length;i++){const img=new Image();img.src=Art.url(nums[i]);await img.decode();const w=nums.length===1?1100:350;ctx.drawImage(img,50+i*(w+15),115,w,nums.length===1?650:510);}ctx.font='21px sans-serif';ctx.fillText('CIMORA / '+r.option+' / 本地交互原型示例，非模型生成结果',50,canvas.height-60);canvas.toBlob(blob=>{if(blob)S.download(blob,'framein-'+t.id+'-demo.png');},'image/png');}catch{S.download({prototype:true,tool:t.title,...r},'framein-'+t.id+'-demo.json');}}
S.tools={renderResult:result,render(c){if(!c.parts[1])return toolList();const t=D.tools.find(t=>t.id===c.parts[1]);return t?detail(t):S.empty('没有找到这个工具','回到工具中心，选择你的下一步。','工具中心','/tools');},saveResult,attach,
onClick(action,el){const t=D.tools.find(v=>v.id===(el.dataset.id||(S.context.parts[0]==='app'?S.context.parts[2]:S.context.parts[1])));if(action==='tool-filter'){S.ui.toolGroup=el.dataset.value;S.render();return true;}if(action==='tool-sample'){loadSample(t);return true;}if(action==='save-tool'){saveResult(t.id);return true;}if(action==='tool-project'){chooseProject(t.id);return true;}if(action==='attach-tool'){attach(t.id,el.dataset.project);return true;}if(action==='download-tool'){downloadResult(t);return true;}if(action==='tool-motion'){const f=S.$('#tool-motion-frame');f.classList.toggle('is-playing');el.textContent=f.classList.contains('is-playing')?'Ⅱ 暂停':'▷ 播放';return true;}if(action==='motion-channel'){S.$$('[data-act="motion-channel"]').forEach(b=>b.classList.toggle('selected',b===el));S.$('#channel-note').textContent=el.dataset.value==='stable'?'稳定底稿可编辑，无真实视频输出。':'增强候选仅为流程示意，不覆盖稳定版，不产生实际费用。';return true;}if(action==='puppet-state'){S.$$('[data-act="puppet-state"]').forEach(b=>b.classList.toggle('selected',b===el));S.$('#puppet-label').textContent=el.textContent;S.$('#puppet-stage').dataset.state=el.dataset.index;return true;}if(action==='panel-up'){const r=record(t),i=Number(el.dataset.index);r.dialogues??=['那家书店，还在原来的地方。','七年了，你还记得我吗？','我以为，你不会再来了。','有些话，写了很久也没寄出去。'];[r.dialogues[i-1],r.dialogues[i]]=[r.dialogues[i],r.dialogues[i-1]];S.save();S.$('#tool-result-body').innerHTML=result(t,r);S.toast('示例对白顺序已调整，画面切格边界为示意。');return true;}return false;},
onSubmit(form){if(form.dataset.form==='tool'){run(form);return true;}return false;},
onInput(el){if(el.id==='tool-search'){S.ui.toolQuery=el.value;const list=D.tools.filter(t=>!t.hidden).filter(t=>(S.ui.toolGroup==='全部'||t.group===S.ui.toolGroup)&&(t.title+t.desc+t.group).includes(el.value));S.$('#tools-grid').innerHTML=list.map(S.public.toolCard).join('')||'<p class="muted">没有匹配的工具。</p>';S.$('#tool-count').textContent=list.length+' 个工具';}if(el.id==='translated-text'){S.$('#translated-bubble').textContent=el.value;const t=currentTool();if(t){record(t).translated=el.value;S.save();}}if(el.id==='rig-range'){S.$('.rig-preview img').style.transform=`rotate(${Number(el.value)/3}deg)`;}},
onChange(el){if(el.id==='tool-file'&&el.files.length){const t=currentTool(),file=el.files[0];if(file.size>20e6){S.toast('原型本机预览请选择 20 MB 以内素材。');el.value='';return;}const url=URL.createObjectURL(file);uploadURLs[t.id]=url;S.$('#upload-preview').innerHTML=file.type.startsWith('image/')?`<img src="${url}" alt="本机素材预览">`:`<b>▤</b><strong>${esc(file.name)}</strong>`;S.$('#input-source').textContent=el.files.length+' 份本机素材已选择';S.state.results[t.id]={...(record(t)||{}),source:'upload',inputName:file.name};S.save();}if(el.dataset.resultDialogue!==undefined){const t=currentTool(),r=record(t);r.dialogues??=['那家书店，还在原来的地方。','七年了，你还记得我吗？','我以为，你不会再来了。','有些话，写了很久也没寄出去。'];r.dialogues[Number(el.dataset.resultDialogue)]=el.value;S.save();}},afterRender(){}}
})();
